import React, { useEffect, useState } from "react";
import axios from "axios";

const JobNotifications = () => {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/VJISS/job_notifications")
      .then((res) => {
        setJobs(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        setLoading(false);
      });
  }, []);

  if (loading) return <p className="p-6">Loading jobs...</p>;

  return (
    <div className="max-w-6xl mx-auto p-6">
      <h2 className="text-3xl font-bold mb-6">Job Notifications</h2>

      <div className="grid md:grid-cols-2 gap-6">
        {jobs.map((job) => (
          <div
            key={job.notification_id}
            className="border rounded-lg p-4 shadow hover:shadow-md"
          >
            <div className="flex items-center gap-4">
              <img
                src={job.company_logo}
                alt="logo"
                className="w-16 h-16 object-cover"
              />
              <div>
                <h3 className="text-xl font-semibold">{job.job_title}</h3>
                <p className="text-gray-600">{job.company_name}</p>
                <p className="text-sm text-gray-500">{job.location}</p>
              </div>
            </div>

            <p className="mt-3 text-sm">
              <strong>Description:</strong> {job.job_description}
            </p>

            <p className="mt-2 text-sm">
              <strong>Requirements:</strong> {job.requirements}
            </p>

            <a
              href={job.link}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-block mt-3 text-blue-600 underline"
            >
              Apply Now
            </a>
          </div>
        ))}
      </div>
    </div>
  );
};

export default JobNotifications;
